SELECT 
FROM et_question


        AND name LIKE CONCAT('%', #{name}, '%')


        AND question_type_id = #{questionTypeId}


        AND group_id = #{groupId}


        AND is_visible = #{isVisible}


        AND creator = #{creator}


        AND difficulty = #{difficulty}


ORDER BY id DESC
LIMIT #{offset}, #{limit}

